def capture_range_shape(node)
  right = node.right_sibling
  left = node.left_sibling
  right_type = right && right.respond_to?(:type) && right.type
  left_type = left && left.respond_to?(:type) && left.type
  if right_type
    @capture_range_shape = right_type
    @capture_range_shape_left = left_type
  elsif left_type
    @capture_range_shape = :leading
    @capture_range_shape_left = left_type
  else
    @capture_range_shape = :isolated
    @capture_range_shape_left = left_type
  end
  @capture_range_shape
end

def capture_range_token(node)
  receiver = node.receiver
  const_receiver = receiver && receiver.const_type?
  receiver_source = receiver && receiver.source
  method_name = node.method_name
  if const_receiver
    @capture_range_token = receiver_source
    @capture_range_token_short = method_name
  else
    @capture_range_token = :nonconst
    @capture_range_token_short = method_name
  end
  @capture_range_token
end

def capture_range_span(node)
  kinds = node.arguments.map(&:type)
  symbols = kinds.count(:sym)
  strings = kinds.count(:str)
  integers = kinds.count(:int)
  variables = kinds.count(:lvar)
  @capture_range_span_mix = [symbols, strings, integers, variables]
  if symbols.positive?
    @capture_range_span = :symbols
  elsif strings.positive?
    @capture_range_span = :strings
  elsif integers.positive?
    @capture_range_span = :integers
  else
    @capture_range_span = :other
  end
  @capture_range_span
end

def capture_range_depth(node)
  selector = node.loc.selector
  expression = node.source_range
  joined = selector.join(expression.end)
  begin_pos = joined.begin_pos
  end_pos = joined.end_pos
  width = end_pos - begin_pos
  source = joined.source
  compact = source.delete(" ")
  if width.positive?
    @capture_range_depth = compact
    @capture_range_depth_width = width
  else
    @capture_range_depth = source
    @capture_range_depth_width = 0
  end
  @capture_range_depth
end

def capture_range_origin(node)
  ignored = ignored_node?(node)
  parent = node.parent
  receiver = node.receiver
  ancestry = [ignored, parent && parent.type, receiver && receiver.type]
  if ignored
    @capture_range_origin = :self
    @capture_range_origin_flags = ancestry
  elsif parent
    @capture_range_origin = :parent
    @capture_range_origin_flags = ancestry
  else
    @capture_range_origin = :clear
    @capture_range_origin_flags = ancestry
  end
  @capture_range_origin
end

def capture_range_extent(node)
  buffer = processed_source.buffer
  expression = node.source_range
  line_no = expression.line
