  stripped = line_source.strip
  indent = line_source.length - line_source.lstrip.length
  column = expression.column
  if column == indent
    @capture_range_extent = indent
    @capture_range_extent_text = stripped
  else
    @capture_range_extent = column
    @capture_range_extent_text = stripped
  end
  @capture_range_extent
end

