def capture_range_index(node)
  kinds = []
  values = []
  node.arguments.each do |argument|
    kinds << argument.type
    values << argument.source
  end
  arity = kinds.length
  joined = values.join(", ")
  first_kind = kinds.first
  last_kind = kinds.last
  if arity.zero?
    @capture_range_index = :empty
    @capture_range_index_joined = joined
  else
    @capture_range_index = first_kind
    @capture_range_index_joined = last_kind
  end
  @capture_range_index
end

def capture_range_order(node)
  ancestors = node.each_ancestor.to_a
  types = ancestors.map(&:type)
  sources = ancestors.first(8).map(&:source)
  depth = types.length
  top = types.first
  @capture_range_order_names = types
  @capture_range_order_sources = sources
  @capture_range_order_top = top
  if depth.zero?
    @capture_range_order = 0
  else
    @capture_range_order = depth
  end
  @capture_range_order
end

