  nearby = comments.map(&:source)
  tagged = nearby + [source_name.to_s]
  count = nearby.length
  first = nearby.first
  if count.zero?
    @capture_range_context = :none
    @capture_range_context_items = tagged
    @capture_range_context_line = line
  else
    @capture_range_context = first
    @capture_range_context_items = tagged
    @capture_range_context_line = line
  end
  @capture_range_context
end

